/// <summary>
/// DP class for SO Manifest DangerousGoods report
/// </summary>
[SrsReportParameterAttribute(classStr(METCommonReportContract))]
public class METSalesDangerousGoodsManifestDP extends SrsReportDataProviderPreProcessTempDB
{
    METSalesDangerousGoodsManifestTmp metSalesDangerousGoodsManifestTmp;
    METSalesDangerousGoodsManifestLineTmp metSalesDangerousGoodsManifestLineTmp;
    RecordInsertList lineList;
    METBundleGuid         bundleHeaderReportGuid;
    METBundleGuid         headerReportGuid;

}

Method.Source:
/// <summary>
/// Set the bundling guid values to the tmp tables
/// </summary>
/// <param name = "_bundleHeaderReportGuid">Bundle header report guid</param>
/// <param name = "_headerReportGuid">Header report guid</param>
public void setBundlingGuid(METBundleGuid     _bundleHeaderReportGuid, METBundleGuid    _headerReportGuid)
{
    bundleHeaderReportGuid = _bundleHeaderReportGuid;
    headerReportGuid = _headerReportGuid;
}

/// <summary>
/// Get METSalesDangerousGoodsManifestTmp
/// </summary>
/// <returns>METSalesDangerousGoodsManifestTmp</returns>
[SrsReportDataSetAttribute(tableStr(METSalesDangerousGoodsManifestTmp))]
public METSalesDangerousGoodsManifestTmp getMETSalesDangerousGoodsManifestTmp()
{
    select metSalesDangerousGoodsManifestTmp;
    return metSalesDangerousGoodsManifestTmp;
}

/// <summary>
/// Get METSalesDangerousGoodsManifestLineTmp
/// </summary>
/// <returns>METSalesDangerousGoodsManifestLineTmp</returns>
[SrsReportDataSetAttribute(tableStr(METSalesDangerousGoodsManifestLineTmp))]
public METSalesDangerousGoodsManifestLineTmp getMETSalesDangerousGoodsManifestLineTmp()
{
    select metSalesDangerousGoodsManifestLineTmp;
    return metSalesDangerousGoodsManifestLineTmp;
}

/// <summary>
/// Report business logic
/// </summary>
public void processReport()
{
    if (this.isPrintReport())
    {
        METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeader, metSalesOrderShipmentLoadHeaderCountStop;
        METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLines;
        METCommonReportContract             contract = this.parmDataContract();
        InventTable inventTable;
        Qty sumOfItemUnit;
        int countOfStop;
        METDangerousGoodsManifestDocNum docNumSeq;
        NumberSequenceReference numberSequenceReference;

        lineList = new RecordInsertList(tableNum(METSalesDangerousGoodsManifestLineTmp), true, true, true, true, true, metSalesDangerousGoodsManifestLineTmp);

        select firstonly ToWarehouse, Route, RouteStopNum, ShipmentId, LoadId, Warehouse from metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.RecId == contract.parmRecId()
        exists join metSalesOrderShipmentLoadLines
        where metSalesOrderShipmentLoadLines.shipmentid == metSalesOrderShipmentLoadHeader.ShipmentId
        exists join inventTable
            where inventTable.ItemId == metSalesOrderShipmentLoadLines.ItemId;

        if (metSalesOrderShipmentLoadHeader)
        {
            this.insertHeaderData(metSalesOrderShipmentLoadHeader);
        }

        while select  ItemId, Quantity, RecId, LineNum, OrderNum, InventTransId, PickedQty from metSalesOrderShipmentLoadLines
        join RecId, RouteStopNum, ShipmentId, LoadId from metSalesOrderShipmentLoadHeader
        where  metSalesOrderShipmentLoadLines.shipmentid == metSalesOrderShipmentLoadHeader.ShipmentId
        && metSalesOrderShipmentLoadHeader.RecId == contract.parmRecId()
        exists join inventTable
        where inventTable.ItemId == metSalesOrderShipmentLoadLines.ItemId
        {
            if (this.isInsertLineData(metSalesOrderShipmentLoadLines.ItemId))
            {
                this.insertLineData(metSalesOrderShipmentLoadLines, metSalesOrderShipmentLoadHeader);
            }
        }
        lineList.insertDatabase();

        select sum(ItemUnit)
        from metSalesDangerousGoodsManifestLineTmp;

        sumOfItemUnit = metSalesDangerousGoodsManifestLineTmp.ItemUnit;

        update_recordset metSalesDangerousGoodsManifestLineTmp
        setting KGLAmount = sumOfItemUnit;

        //Reprint number sequence logic
        metSalesOrderShipmentLoadHeader = METSalesOrderShipmentLoadHeader::findByRecId(contract.parmRecId());

        if (metSalesOrderShipmentLoadHeader.ManifestDGNumSeq)
        {
            update_recordset metSalesDangerousGoodsManifestTmp
        setting ManifestDocumentNo = metSalesOrderShipmentLoadHeader.ManifestDGNumSeq;
        }
        else
        {
            numberSequenceReference = NumberSeqReference::findReference(extendedTypeNum(METDangerousGoodsManifestDocNum));

            if (numberSequenceReference.RecId)
            {
                docNumSeq = NumberSeq::newGetNum(numberSequenceReference).num();
                if (docNumSeq)
                {
                    METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeaderLocal;

                    update_recordset metSalesOrderShipmentLoadHeaderLocal
                setting ManifestDGNumSeq = docNumSeq
                where metSalesOrderShipmentLoadHeaderLocal.LoadId == metSalesOrderShipmentLoadHeader.LoadId;

                    update_recordset metSalesDangerousGoodsManifestTmp
                setting ManifestDocumentNo = docNumSeq;
                }
            }
        }

        //Count number of stops
        select count(RecId)
        from metSalesOrderShipmentLoadHeaderCountStop
        group by metSalesOrderShipmentLoadHeaderCountStop.RouteStopNum, metSalesOrderShipmentLoadHeaderCountStop.ShipmentId
        where metSalesOrderShipmentLoadHeaderCountStop.RouteStopNum != 0
        && metSalesOrderShipmentLoadHeaderCountStop.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId;

        countOfStop = metSalesOrderShipmentLoadHeaderCountStop.RecId;

        update_recordset metSalesDangerousGoodsManifestTmp
        setting RouteStopNum = countOfStop;
    }
}

/// <summary>
/// Insert into header table
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
public void insertHeaderData(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    InventLocation inventLocation = InventLocation::find(_metSalesOrderShipmentLoadHeader.Warehouse);        

    METIndustryKeyTable metIndustryKeyTable;

    select firstonly CompanyName, IndustryKey  from metIndustryKeyTable
        where metIndustryKeyTable.IndustryKey == inventLocation.METWHSubEntity;

    //metSalesDangerousGoodsManifestTmp.MFGLogo = SysDocuBrandImages::getImage(inventLocationTo.METWHSubEntity); //task 226482
    metSalesDangerousGoodsManifestTmp.IndustryKey = metIndustryKeyTable.IndustryKey;//task 218182
    metSalesDangerousGoodsManifestTmp.CompanyName = metIndustryKeyTable.CompanyName;
    metSalesDangerousGoodsManifestTmp.BranchName = inventLocation.Name;
    metSalesDangerousGoodsManifestTmp.BranchAddress = inventLocation.address();
    metSalesDangerousGoodsManifestTmp.Route = _metSalesOrderShipmentLoadHeader.Route;
    metSalesDangerousGoodsManifestTmp.RouteStopNum = _metSalesOrderShipmentLoadHeader.RouteStopNum;
    metSalesDangerousGoodsManifestTmp.AnyClass = this.checkClass(_metSalesOrderShipmentLoadHeader);
    metSalesDangerousGoodsManifestTmp.UN = this.getUN(_metSalesOrderShipmentLoadHeader.ShipmentId);
    metSalesDangerousGoodsManifestTmp.UnitOfMeasure = this.getUOM(_metSalesOrderShipmentLoadHeader.ShipmentId);

    CompanyInfo companyInfo;

    select firstonly METDocumentNum, METRevision, METRevisionDate
        from companyInfo
        where companyInfo.DataArea == curExt();

    metSalesDangerousGoodsManifestTmp.DocumentNo = companyInfo.METDocumentNum;
    metSalesDangerousGoodsManifestTmp.Revision = companyInfo.METRevision;
    metSalesDangerousGoodsManifestTmp.RevisionDate = companyInfo.METRevisionDate;

    metSalesDangerousGoodsManifestTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
    metSalesDangerousGoodsManifestTmp.DangerousGoodsManifestHeaderGuidStr = headerReportGuid;
    metSalesDangerousGoodsManifestTmp.insert();
}

/// <summary>
/// Insert into Line data
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadLines">METSalesOrderShipmentLoadLines</param>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
public void insertLineData(METSalesOrderShipmentLoadLines _metSalesOrderShipmentLoadLines, METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    SalesLine salesLine;
    InventDim inventDim;
    InventLocation inventLocation;
    METInventLocation metInventLocation;
    CustTable custTable;
    HMIMItemMaterial hmimItemMaterial;
    METInventTable metInventTable;
    InventTableModule  inventTableModule;

    custTable = CustTable::find(SalesTable::find(_metSalesOrderShipmentLoadLines.OrderNum).CustAccount);

    metSalesDangerousGoodsManifestLineTmp.CustAccount = custTable.AccountNum;
    if (custTable.AccountNum)
    {
        metSalesDangerousGoodsManifestLineTmp.CustName = custTable.name();
    }
    metSalesDangerousGoodsManifestLineTmp.Stop = _metSalesOrderShipmentLoadHeader.RouteStopNum;
    metSalesDangerousGoodsManifestLineTmp.PG1 = this.checkClassForItem(_metSalesOrderShipmentLoadLines.ItemId);
    metSalesDangerousGoodsManifestLineTmp.ItemId = _metSalesOrderShipmentLoadLines.ItemId;
    metSalesDangerousGoodsManifestLineTmp.ItemDesc = InventTable::find(_metSalesOrderShipmentLoadLines.ItemId).itemName();

    select firstonly ClassCode, DivisionCode, IdentificationCode, PackingGroupCode, PackCode, UnitOfMeasure, LabelCode, MaterialDescription, Qty
        from hmimItemMaterial
        where hmimItemMaterial.ItemId == _metSalesOrderShipmentLoadLines.ItemId;

    metSalesDangerousGoodsManifestLineTmp.ClassCode = hmimItemMaterial.ClassCode;
    metSalesDangerousGoodsManifestLineTmp.SubRisk = hmimItemMaterial.DivisionCode;
    metSalesDangerousGoodsManifestLineTmp.UN = hmimItemMaterial.IdentificationCode;
    metSalesDangerousGoodsManifestLineTmp.PackingGroupCode = hmimItemMaterial.PackingGroupCode;
    metSalesDangerousGoodsManifestLineTmp.PackType = hmimItemMaterial.PackCode;
    metSalesDangerousGoodsManifestLineTmp.UnitOfMeasure = hmimItemMaterial.UnitOfMeasure;
    metSalesDangerousGoodsManifestLineTmp.SalesOrder = _metSalesOrderShipmentLoadHeader.ShipmentId;

    select firstonly ItemSize from metInventTable
        where metInventTable.ItemId == _metSalesOrderShipmentLoadLines.ItemId;

    metSalesDangerousGoodsManifestLineTmp.ItemSize = any2Str(hmimItemMaterial.Qty);

    CustInvoiceTrans custInvoiceTrans;

    if (_metSalesOrderShipmentLoadLines.InventTransId)
    {
        select firstonly Qty from custInvoiceTrans
            where custInvoiceTrans.InventTransId == _metSalesOrderShipmentLoadLines.InventTransId;
    }

    metSalesDangerousGoodsManifestLineTmp.Hazchem = hmimItemMaterial.LabelCode;

    const str each = 'EA';

    METSalesUnit salesUnit = this.getSalesOrderUnit(_metSalesOrderShipmentLoadLines);

    if (salesUnit == each)
    {
        metSalesDangerousGoodsManifestLineTmp.ItemPack = 1;
    }
    else
    {
        metSalesDangerousGoodsManifestLineTmp.ItemPack = (UnitOfMeasureConversion::findByConversion(UnitOfMeasure::findBySymbol(salesUnit).RecId,
                                                UnitOfMeasure::findBySymbol(each).RecId,
                                                EcoResProduct::findByProductNumber(_metSalesOrderShipmentLoadLines.ItemId).RecId).Factor);
    }

    // Get the unit of measure for the item from InventTableModule for inventory unit conversion
    select firstonly UnitId from inventTableModule
        where inventTableModule.ItemId      == _metSalesOrderShipmentLoadLines.ItemId
        && inventTableModule.ModuleType == ModuleInventPurchSales::Invent;


    Qty qtyInSalesUOM = UnitOfMeasureConverter::convert(_metSalesOrderShipmentLoadLines.PickedQty,
                                                                UnitOfMeasure::unitOfMeasureIdBySymbol(inventTableModule.UnitId),
                                                                UnitOfMeasure::unitOfMeasureIdBySymbol(salesUnit),
                                                                NoYes::No,
                                                                EcoResProduct::findByProductNumber(_metSalesOrderShipmentLoadLines.itemid).RecId,
                                                                NoYes::No);

    // Change the qty value based on the unit of measure conversion factor
    metSalesDangerousGoodsManifestLineTmp.Qty = qtyInSalesUOM; //custInvoiceTrans.Qty;

    metSalesDangerousGoodsManifestLineTmp.Type = hmimItemMaterial.MaterialDescription;
    metSalesDangerousGoodsManifestLineTmp.ItemUnit = hmimItemMaterial.Qty * metSalesDangerousGoodsManifestLineTmp.ItemPack * metSalesDangerousGoodsManifestLineTmp.Qty;
    metSalesDangerousGoodsManifestLineTmp.BundleReportHeaderGuidStr = bundleHeaderReportGuid;
    metSalesDangerousGoodsManifestLineTmp.DangerousGoodsManifestHeaderGuidStr = headerReportGuid;

    lineList.add(metSalesDangerousGoodsManifestLineTmp);
}

/// <summary>
/// This method is used to check if item belongs to a Divison or not
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadHeader">METSalesOrderShipmentLoadHeader</param>
/// <returns>boolean</returns>
public boolean checkClass(METSalesOrderShipmentLoadHeader _metSalesOrderShipmentLoadHeader)
{
    METSalesOrderShipmentLoadLines metSalesOrderShipmentLoadLines;
    HMIMItemMaterial hmIMItemMaterial;
    const str twoOne = '2.1';
    const str twoThree = '2.3';
    const str pgOne = 'PG1';

    select firstonly RecId from hmIMItemMaterial
        join metSalesOrderShipmentLoadLines
        where hmIMItemMaterial.ItemId == metSalesOrderShipmentLoadLines.ItemId
        && metSalesOrderShipmentLoadLines.ShipmentId == _metSalesOrderShipmentLoadHeader.ShipmentId
        && ( hmIMItemMaterial.DivisionCode == twoOne || hmIMItemMaterial.DivisionCode == twoThree || hmIMItemMaterial.DivisionCode == pgOne );

    if (hmIMItemMaterial)
    {
        return true;
    }

    return false;
}

/// <summary>
/// GET unique UN number
/// </summary>
/// <param name = "_shipmentId">MetShipmentId</param>
/// <returns>HMIMIdentificationCode</returns>
public HMIMIdentificationCode getUN(MetShipmentId _shipmentId)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeaderLocal;
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLinesLocal;
    HMIMItemMaterial                    hmimItemMaterialLocal;
    HMIMIdentificationCode              hmimIdentificationCode;

    while select IdentificationCode from hmimItemMaterialLocal
        group by IdentificationCode
        exists join metSalesOrderShipmentLoadLinesLocal
        where hmimItemMaterialLocal.ItemId == metSalesOrderShipmentLoadLinesLocal.ItemId
        exists join metSalesOrderShipmentLoadHeaderLocal
        where metSalesOrderShipmentLoadHeaderLocal.ShipmentId == metSalesOrderShipmentLoadLinesLocal.ShipmentId
        && metSalesOrderShipmentLoadHeaderLocal.ShipmentId == _shipmentId
    {
        hmimIdentificationCode += " " + hmimItemMaterialLocal.IdentificationCode;
    }

    return hmimIdentificationCode;
}

/// <summary>
/// GET unique UOM
/// </summary>
/// <param name = "_shipmentId">MetShipmentId</param>
/// <returns>UnitOfMeasureSymbol</returns>
public UnitOfMeasureSymbol getUOM(MetShipmentId _shipmentId)
{
    METSalesOrderShipmentLoadHeader     metSalesOrderShipmentLoadHeaderLocal;
    METSalesOrderShipmentLoadLines      metSalesOrderShipmentLoadLinesLocal;
    HMIMItemMaterial                    hmimItemMaterialLocal;
    UnitOfMeasureSymbol                 unitOfMeasureSymbol;

    while select UnitOfMeasure from hmimItemMaterialLocal
        group by UnitOfMeasure
        exists join metSalesOrderShipmentLoadLinesLocal
        where hmimItemMaterialLocal.ItemId == metSalesOrderShipmentLoadLinesLocal.ItemId
        exists join metSalesOrderShipmentLoadHeaderLocal
        where metSalesOrderShipmentLoadHeaderLocal.ShipmentId == metSalesOrderShipmentLoadLinesLocal.ShipmentId
        && metSalesOrderShipmentLoadHeaderLocal.ShipmentId == _shipmentId
    {
        unitOfMeasureSymbol += " " + hmimItemMaterialLocal.UnitOfMeasure;
    }

    return unitOfMeasureSymbol;
}

/// <summary>
/// This method is used to check if item belongs to a Divison or not
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <returns>boolean</returns>
public boolean checkClassForItem(ItemId _itemId)
{
    HMIMItemMaterial hmIMItemMaterial;
    const str twoOne = '2.1';
    const str twoThree = '2.3';
    const str pgOne = 'PG1';

    select firstonly RecId from hmIMItemMaterial
        where hmIMItemMaterial.ItemId == _itemId
        && ( hmIMItemMaterial.DivisionCode == twoOne || hmIMItemMaterial.DivisionCode == twoThree || hmIMItemMaterial.DivisionCode == pgOne );

    if (hmIMItemMaterial)
    {
        return true;
    }

    return false;
}

/// <summary>
/// Get sales order unit from default order setting
/// </summary>
/// <param name = "_metSalesOrderShipmentLoadLines">_metSalesOrderShipmentLoadLines</param>
/// <returns>METSalesUnit</returns>
public METSalesUnit getSalesOrderUnit(METSalesOrderShipmentLoadLines _metSalesOrderShipmentLoadLines)
{
    InventItemSalesSetup inventItemSalesSetup;
    InventDim inventDimSOLine;
    InventDim inventDimInventItemSalesSetup;

    select firstonly METSalesUnit from inventItemSalesSetup
        exists join inventDimInventItemSalesSetup
        where inventDimInventItemSalesSetup.inventDimId == inventItemSalesSetup.InventDimId
        && inventItemSalesSetup.ItemId == _metSalesOrderShipmentLoadLines.ItemId
        exists join inventDimSOLine
        where inventDimSOLine.inventDimId == SalesLine::find(_metSalesOrderShipmentLoadLines.OrderNum, _metSalesOrderShipmentLoadLines.LineNum).InventDimId
        && inventDimSOLine.InventSiteId == inventDimInventItemSalesSetup.InventSiteId;

    return inventItemSalesSetup.METSalesUnit;
}

/// <summary>
/// Determines whether the report should be printed based on shipment load header data.
/// </summary>
/// <remarks>
/// Performs two checks:
/// 1. Verifies if the related InventTable record has HMIMIndicator set to Yes.
/// 2. If not found, verifies if the related HMIMItemMaterial record has EnviroDangerous set to Yes.
/// Returns true if either condition is satisfied.
/// </remarks>
/// <returns>
/// Boolean value indicating whether the report should be printed.
/// </returns>
private boolean isPrintReport()
{
    boolean ret = false;

    METSalesOrderShipmentLoadHeader metSalesOrderShipmentLoadHeader;
    METSalesOrderShipmentLoadLines  metSalesOrderShipmentLoadLines;
    InventTable                     inventTable;
    METCommonReportContract         contract = this.parmDataContract();
    HMIMItemMaterial                hmimItemMaterial;

    // First check: InventTable condition
    select firstonly metSalesOrderShipmentLoadHeader
    where metSalesOrderShipmentLoadHeader.RecId == contract.parmRecId()
    exists join metSalesOrderShipmentLoadLines
        where metSalesOrderShipmentLoadLines.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
    exists join inventTable
        where inventTable.ItemId == metSalesOrderShipmentLoadLines.ItemId
        && inventTable.HMIMIndicator == NoYes::Yes;

    if (metSalesOrderShipmentLoadHeader.RecId)
    {
        ret = true;
    }

    // Second check: HMIMItemMaterial condition
    if (!ret)
    {
        select firstonly metSalesOrderShipmentLoadHeader
        where metSalesOrderShipmentLoadHeader.RecId == contract.parmRecId()
        exists join metSalesOrderShipmentLoadLines
            where metSalesOrderShipmentLoadLines.ShipmentId == metSalesOrderShipmentLoadHeader.ShipmentId
        exists join hmimItemMaterial
            where hmimItemMaterial.ItemId == metSalesOrderShipmentLoadLines.ItemId
            && hmimItemMaterial.EnviroDangerous == NoYes::Yes;

        if (metSalesOrderShipmentLoadHeader.RecId)
        {
            ret = true;
        }
    }

    return ret;
}

// <summary>
/// Determines whether line data should be inserted for a given item.
/// </summary>
/// <param name="_itemId">
/// The ItemId to evaluate.
/// </param>
/// <remarks>
/// Performs two checks:
/// 1. Verifies if the InventTable record for the item has HMIMIndicator set to Yes.
/// 2. If not found, verifies if the HMIMItemMaterial record for the item has EnviroDangerous set to Yes.
/// Returns true if either condition is satisfied.
/// </remarks>
/// <returns>
/// Boolean value indicating whether line data should be inserted.
/// </returns>
private boolean isInsertLineData(ItemId _itemId)
{
    boolean ret = false;

    InventTable inventTable;
    HMIMItemMaterial hmimItemMaterial;

    // First check: InventTable condition
    select firstonly inventTable
        where inventTable.ItemId == _itemId
        && inventTable.HMIMIndicator == NoYes::Yes;

    if (inventTable.RecId)
    {
        ret = true;
    }

    // Second check: HMIMItemMaterial condition
    if (!ret)
    {
        select firstonly hmimItemMaterial
            where hmimItemMaterial.ItemId == _itemId
            && hmimItemMaterial.EnviroDangerous == NoYes::Yes;

        if (hmimItemMaterial.RecId)
        {
            ret = true;
        }
    }

    return ret;
}
